// ── Disease Prediction ──────────────────────────────────────────────────────
function PredictPage() {
  const [symptoms, setSymptoms] = useState([]);
  const [form, setForm] = useState({ symptom1: "", symptom2: "", symptom3: "" });
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState("");

  useEffect(() => { get("/symptoms").then(setSymptoms); }, []);

  const predict = async () => {
    if (!form.symptom1 || !form.symptom2 || !form.symptom3) { setErr("Please select all 3 symptoms"); return; }
    setLoading(true); setErr(""); setResult(null);
    const res = await post("/predict/disease", form);
    setLoading(false);
    if (res.error) setErr(res.error);
    else setResult(res);
  };

  return (
    <div className="space-y-5 max-w-2xl">
      <div>
        <h2 className="text-xl font-bold text-gray-800">Disease Prediction</h2>
        <p className="text-gray-500 text-sm mt-1">Select 3 symptoms to predict possible disease using Naive Bayes ML</p>
      </div>
      <Card>
        <Alert msg={err} type="error" />
        <div className="space-y-4">
          <Select label="Symptom 1" options={symptoms} value={form.symptom1} onChange={e => setForm({...form, symptom1: e.target.value})} />
          <Select label="Symptom 2" options={symptoms.filter(s => s !== form.symptom1)} value={form.symptom2} onChange={e => setForm({...form, symptom2: e.target.value})} />
          <Select label="Symptom 3" options={symptoms.filter(s => s !== form.symptom1 && s !== form.symptom2)} value={form.symptom3} onChange={e => setForm({...form, symptom3: e.target.value})} />
          <Btn onClick={predict} disabled={loading} cls="w-full bg-green-600 text-white hover:bg-green-700">
            {loading ? "Predicting..." : "Predict Disease"}
          </Btn>
        </div>
      </Card>
      {result && (
        <Card>
          <h3 className="font-semibold text-gray-700 mb-4">Prediction Results</h3>
          <div className="bg-green-50 rounded-xl p-4 mb-4 text-center">
            <div className="text-3xl mb-1">🏥</div>
            <div className="text-xl font-bold text-green-800">{result.predicted}</div>
            <div className="text-sm text-green-600 mt-1">Confidence: <strong>{result.confidence}%</strong></div>
          </div>
          <div className="space-y-2">
            <p className="text-sm font-medium text-gray-600 mb-2">Top 3 Predictions:</p>
            {result.top3?.map((r, i) => (
              <div key={i} className="flex items-center gap-3">
                <div className="text-sm text-gray-600 w-4">{i+1}.</div>
                <div className="flex-1">
                  <div className="flex justify-between text-sm mb-1">
                    <span className="font-medium">{r.disease}</span>
                    <span className="text-gray-500">{r.confidence}%</span>
                  </div>
                  <div className="h-2 bg-gray-100 rounded-full"><div className="h-2 bg-green-500 rounded-full" style={{width: `${r.confidence}%`}} /></div>
                </div>
              </div>
            ))}
          </div>
          <p className="text-xs text-gray-400 mt-4">⚠️ This is for informational purposes only. Please consult a healthcare professional.</p>
        </Card>
      )}
    </div>
  );
}

// ── Drug Recommendation ─────────────────────────────────────────────────────
function DrugPage() {
  const [symptoms, setSymptoms] = useState([]);
  const [form, setForm] = useState({ symptom1: "", symptom2: "", symptom3: "", disease: "", age: "30", gender: "Any", severity: "Mild" });
  const [result, setResult] = useState(null);
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState("");
  const [predicted, setPredicted] = useState("");

  const diseases = ["Flu","Common Cold","COVID-19","Food Poisoning","Dengue","Pneumonia","Allergy","Gastritis","Typhoid","Malaria"];

  useEffect(() => {
    get("/symptoms").then(setSymptoms);
    get("/recommend/history").then(r => Array.isArray(r) && setHistory(r));
  }, []);

  const autoPredict = async () => {
    if (!form.symptom1 || !form.symptom2 || !form.symptom3) { setErr("Select 3 symptoms first"); return; }
    setLoading(true); setErr("");
    const res = await post("/predict/disease", { symptom1: form.symptom1, symptom2: form.symptom2, symptom3: form.symptom3 });
    setLoading(false);
    if (res.predicted) { setPredicted(res.predicted); setForm(f => ({...f, disease: res.predicted})); }
  };

  const recommend = async () => {
    if (!form.disease) { setErr("Please select or predict a disease"); return; }
    setLoading(true); setErr(""); setResult(null);
    const res = await post("/recommend/drug", { disease: form.disease, age: form.age, gender: form.gender, severity: form.severity });
    setLoading(false);
    if (res.error) setErr(res.error);
    else { setResult(res); get("/recommend/history").then(r => Array.isArray(r) && setHistory(r)); }
  };

  const statusColor = (s) => ({ Mild: "green", Moderate: "yellow", Severe: "red" }[s] || "gray");

  return (
    <div className="space-y-5 max-w-2xl">
      <div>
        <h2 className="text-xl font-bold text-gray-800">Drug Recommendation</h2>
        <p className="text-gray-500 text-sm mt-1">Get Ayurvedic medicine recommendations based on disease and symptoms</p>
      </div>
      <Card>
        <Alert msg={err} type="error" />
        <p className="text-sm font-medium text-gray-600 mb-3">Step 1: Select symptoms to auto-predict disease</p>
        <div className="grid grid-cols-3 gap-3 mb-3">
          <Select options={symptoms} value={form.symptom1} onChange={e => setForm({...form, symptom1: e.target.value})} label="Symptom 1" />
          <Select options={symptoms.filter(s => s !== form.symptom1)} value={form.symptom2} onChange={e => setForm({...form, symptom2: e.target.value})} label="Symptom 2" />
          <Select options={symptoms.filter(s => s !== form.symptom1 && s !== form.symptom2)} value={form.symptom3} onChange={e => setForm({...form, symptom3: e.target.value})} label="Symptom 3" />
        </div>
        <Btn onClick={autoPredict} disabled={loading} cls="bg-blue-600 text-white hover:bg-blue-700 mb-4 text-xs">🔬 Auto-Predict Disease</Btn>
        {predicted && <div className="bg-blue-50 rounded-lg p-2 mb-3 text-sm text-blue-700">Predicted: <strong>{predicted}</strong></div>}
        <hr className="my-4" />
        <p className="text-sm font-medium text-gray-600 mb-3">Step 2: Enter details for recommendation</p>
        <div className="grid grid-cols-2 gap-3">
          <Select label="Disease" options={diseases} value={form.disease} onChange={e => setForm({...form, disease: e.target.value})} />
          <Input label="Age" type="number" value={form.age} onChange={e => setForm({...form, age: e.target.value})} />
          <Select label="Gender" options={["Male","Female","Any"]} value={form.gender} onChange={e => setForm({...form, gender: e.target.value})} />
          <Select label="Severity" options={["Mild","Moderate","Severe"]} value={form.severity} onChange={e => setForm({...form, severity: e.target.value})} />
        </div>
        <Btn onClick={recommend} disabled={loading} cls="w-full bg-green-600 text-white hover:bg-green-700 mt-4">
          {loading ? "Finding medicines..." : "💊 Get Recommendations"}
        </Btn>
      </Card>

      {result && result.recommendations?.length > 0 && (
        <Card>
          <h3 className="font-semibold text-gray-700 mb-4">Top Recommended Medicines for <span className="text-green-600">{result.disease}</span></h3>
          <div className="space-y-4">
            {result.recommendations.map((r, i) => (
              <div key={i} className="border border-green-100 rounded-xl p-4 bg-green-50">
                <div className="flex justify-between items-start mb-2">
                  <div>
                    <span className="text-xs text-green-600 font-medium">#{i+1} Recommended</span>
                    <h4 className="font-bold text-gray-800">{r.drug}</h4>
                  </div>
                  <div className="text-right">
                    <Badge text={r.severity} color={statusColor(r.severity)} />
                    <div className="text-xs text-gray-500 mt-1">Confidence: {r.confidence}%</div>
                  </div>
                </div>
                <div className="grid grid-cols-1 gap-2 text-sm">
                  <div><span className="font-medium text-gray-600">Dosage: </span><span className="text-gray-700">{r.dosage}</span></div>
                  <div><span className="font-medium text-gray-600">Precautions: </span><span className="text-gray-700">{r.precautions}</span></div>
                  <div><span className="font-medium text-red-500">⚠️ Contraindications: </span><span className="text-gray-700">{r.contraindications}</span></div>
                </div>
              </div>
            ))}
          </div>
          <p className="text-xs text-gray-400 mt-3">⚠️ Consult a certified Ayurvedic practitioner before starting any treatment.</p>
        </Card>
      )}

      {history.length > 0 && (
        <Card>
          <h3 className="font-semibold text-gray-700 mb-3">Recommendation History</h3>
          <div className="space-y-2">
            {history.map((h, i) => (
              <div key={i} className="flex justify-between items-center text-sm py-2 border-b border-gray-50 last:border-0">
                <div>
                  <span className="font-medium">{h.disease}</span>
                  <span className="text-gray-400 mx-2">→</span>
                  <span className="text-green-700">{h.recommended_drug}</span>
                </div>
                <span className="text-xs text-gray-400">{h.created_at?.split("T")[0]}</span>
              </div>
            ))}
          </div>
        </Card>
      )}
    </div>
  );
}

