// ── Main App ─────────────────────────────────────────────────────────────────
export default function App() {
  const [user, setUser] = useState(() => { try { return JSON.parse(localStorage.getItem("user")); } catch { return null; } });
  const [token, setToken] = useState(() => localStorage.getItem("token"));
  const [authView, setAuthView] = useState("login");
  const [page, setPage] = useState("home");

  const handleLogin = (t, u) => { localStorage.setItem("token", t); localStorage.setItem("user", JSON.stringify(u)); setToken(t); setUser(u); };
  const handleLogout = () => { localStorage.clear(); setToken(null); setUser(null); setPage("home"); };

  if (!token || !user) {
    return authView==="login"
      ? <LoginPage onLogin={handleLogin} onSwitch={() => setAuthView("register")} />
      : <RegisterPage onLogin={handleLogin} onSwitch={() => setAuthView("login")} />;
  }

  const renderPage = () => {
    if (page === "admin" && (user.role === "admin" || user.role === "doctor"))
      return <AdminDashboard user={user} logout={handleLogout} setPage={setPage} />;
    switch(page) {
      case "home": return <HomePage setPage={setPage} user={user} />;
      case "predict": return <PredictPage />;
      case "drug": return <DrugPage />;
      case "recommend": return <RecommendPage />;
      case "chat": return <ChatPage />;
      case "doctor": return <DoctorPage user={user} />;
      case "feedback": return <FeedbackPage />;
      case "profile": return <ProfilePage user={user} logout={handleLogout} />;
      default: return <HomePage setPage={setPage} user={user} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-gray-50">
      <Sidebar page={page} setPage={setPage} user={user} logout={handleLogout} />
      <main className="flex-1 p-6 overflow-y-auto">{renderPage()}</main>
    </div>
  );
}
